const { exec } = require('child_process');

module.exports = (on, config) => {
  on('task', {
    exec(command) {
      return new Promise((resolve, reject) => {
        exec(command, (error, stdout, stderr) => {
          if (error) {
            reject(error);
          } else {
            resolve(stdout);
